function drawHoOhRainbowPhoenix(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.5;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  const wingFlap = Math.sin(t * 3.0) * 6.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 44, 32 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Chùm đuôi vàng
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.moveTo(-16, by + 22); ctx.lineTo(-28, by + 40); ctx.lineTo(0, by + 28); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.moveTo(-10, by + 24); ctx.lineTo(0,   by + 44); ctx.lineTo(10, by + 24); ctx.fill();
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.moveTo(0,   by + 28); ctx.lineTo(28,  by + 40); ctx.lineTo(16, by + 22); ctx.fill();

  // 3. Thân đỏ & Bụng trắng
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 15 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(0, by + 14, 10 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 4. Cánh cầu vồng
  const wly = by + wingFlap;
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(-10, by + 6); ctx.lineTo(-44, wly - 18); ctx.lineTo(-18, by + 18); ctx.fill();
  ctx.fillStyle = '#84cc16';
  ctx.beginPath(); ctx.moveTo(-36, wly - 14); ctx.lineTo(-46, wly - 20); ctx.lineTo(-40, wly - 6); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-28, wly - 8);  ctx.lineTo(-38, wly - 14); ctx.lineTo(-32, wly);     ctx.fill();

  const wry = by - wingFlap;
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(10, by + 6); ctx.lineTo(44, wry - 18); ctx.lineTo(18, by + 18); ctx.fill();
  ctx.fillStyle = '#84cc16';
  ctx.beginPath(); ctx.moveTo(36, wry - 14); ctx.lineTo(46, wry - 20); ctx.lineTo(40, wry - 6); ctx.fill();
  ctx.beginPath(); ctx.moveTo(28, wry - 8);  ctx.lineTo(38, wry - 14); ctx.lineTo(32, wry);     ctx.fill();

  // 5. Cổ & Vòng xanh
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.roundRect(-4, by - 6, 8, 14, 3); ctx.fill();
  ctx.fillStyle = '#84cc16';
  ctx.fillRect(-4, by + 2, 8, 3);

  // 6. Đầu
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.arc(0, by - 12, 9, 0, Math.PI * 2); ctx.fill();

  // 7. Mào vàng
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.arc(0,  by - 22, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-4, by - 24, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4,  by - 24, 4, 0, Math.PI * 2); ctx.fill();

  // 8. Mỏ & Mắt
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.moveTo(4, by - 12); ctx.lineTo(18, by - 10); ctx.lineTo(4, by - 6); ctx.fill();
  if (!blink) {
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(2, by - 12, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(1, by - 13, 1, 0, Math.PI * 2); ctx.fill();
  }

  // 9. Chân
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.roundRect(-6, by + 26, 4, 8, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(2,  by + 26, 4, 8, 2); ctx.fill();

  ctx.restore();
}
